<div class="table-wrap"><table><thead><tr><th>Description</th><th class="number">Quantity</th><th class="number">Unit price</th><th class="number">Tax</th><th class="number">Subtotal</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= e($item['description']) ?></td><td class="number"><?= decimal((int)$item['quantity_hundredths']) ?></td><td class="number"><?= money($item['unit_price']) ?></td><td class="number"><?= decimal((int)$item['tax_basis_points']) ?>%</td><td class="number"><?= money($item['subtotal']) ?></td></tr><?php endforeach ?></tbody></table></div><div class="invoice-totals"><div><span>Subtotal</span><span><?= money($invoice['subtotal']) ?></span></div><div><span>Tax</span><span><?= money($invoice['tax_amount']) ?></span></div><div class="grand-total"><strong>Total</strong><strong><?= money($invoice['total']) ?></strong></div></div>
